import java.io.*;import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;
/** Audits Fabric mod bytecode references against Pomme's intermediary Minecraft shim. */
public final class ModAbiAudit {
 record M(String n,String d,boolean method){String key(){return(method?"M ":"F ")+n+d;}}
 static class C{String p;List<String> i=new ArrayList<>();Set<String> m=new HashSet<>();}
 static Map<String,C> shim=new HashMap<>();
 static Map<String,Set<String>> refs=new TreeMap<>(),mc=new TreeMap<>(),mm=new TreeMap<>();
 static void cls(String n,String s){if(n!=null&&n.startsWith("net/minecraft/"))refs.computeIfAbsent(n,k->new TreeSet<>()).add(s);}
 static void typ(Type t,String s){if(t.getSort()==Type.ARRAY)typ(t.getElementType(),s);else if(t.getSort()==Type.OBJECT)cls(t.getInternalName(),s);else if(t.getSort()==Type.METHOD){for(Type x:t.getArgumentTypes())typ(x,s);typ(t.getReturnType(),s);}}
 static boolean has(String o,String k,Set<String> seen){if(o==null||!seen.add(o))return false;if(o.startsWith("java/")||o.startsWith("javax/")||o.startsWith("jdk/")||o.startsWith("sun/"))return jdkHas(o,k);C c=shim.get(o);if(c==null)return false;if(c.m.contains(k)||has(c.p,k,seen))return true;for(String x:c.i)if(has(x,k,seen))return true;return false;}
 static boolean jdkHas(String owner,String key){try{String name=owner.replace('/','.');ClassLoader loader=owner.startsWith("java/")?null:ClassLoader.getPlatformClassLoader();Class<?> type=Class.forName(name,false,loader);for(java.lang.reflect.Method m:type.getDeclaredMethods())if(("M "+m.getName()+org.objectweb.asm.Type.getMethodDescriptor(m)).equals(key))return true;for(java.lang.reflect.Constructor<?> c:type.getDeclaredConstructors())if(("M <init>"+org.objectweb.asm.Type.getConstructorDescriptor(c)).equals(key))return true;for(java.lang.reflect.Field f:type.getDeclaredFields())if(("F "+f.getName()+org.objectweb.asm.Type.getDescriptor(f.getType())).equals(key))return true;return false;}catch(Throwable ignored){return false;}}
 static void check(String o,String n,String d,boolean method,String s){cls(o,s);if(o==null||!o.startsWith("net/minecraft/")||!shim.containsKey(o))return;String k=new M(n,d,method).key();if(!has(o,k,new HashSet<>()))mm.computeIfAbsent(o,x->new TreeSet<>()).add(k+" ["+s+"]");}
 static AnnotationVisitor ann(String s){return new AnnotationVisitor(Opcodes.ASM9){public void visit(String n,Object v){if(v instanceof Type t)typ(t,s);}public void visitEnum(String n,String d,String v){typ(Type.getType(d),s);}public AnnotationVisitor visitAnnotation(String n,String d){typ(Type.getType(d),s);return this;}public AnnotationVisitor visitArray(String n){return this;}};}
 static void load(Path p)throws Exception{try(JarFile j=new JarFile(p.toFile())){var es=j.entries();while(es.hasMoreElements()){var e=es.nextElement();if(!e.getName().endsWith(".class"))continue;try(InputStream in=j.getInputStream(e)){new ClassReader(in).accept(new ClassVisitor(Opcodes.ASM9){C c;public void visit(int v,int a,String n,String s,String p,String[] it){c=new C();c.p=p;if(it!=null)c.i.addAll(Arrays.asList(it));shim.put(n,c);}public FieldVisitor visitField(int a,String n,String d,String s,Object v){c.m.add(new M(n,d,false).key());return null;}public MethodVisitor visitMethod(int a,String n,String d,String s,String[] ex){c.m.add(new M(n,d,true).key());return null;}},ClassReader.SKIP_CODE|ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}}}}
 static void handle(Handle h,String s){cls(h.getOwner(),s);if(h.getDesc().startsWith("("))typ(Type.getMethodType(h.getDesc()),s);else typ(Type.getType(h.getDesc()),s);check(h.getOwner(),h.getName(),h.getDesc(),h.getTag()>Opcodes.H_PUTSTATIC,s);}
 static void scan(Path p)throws Exception{String mod=p.getFileName().toString();try(JarFile j=new JarFile(p.toFile())){var es=j.entries();while(es.hasMoreElements()){var e=es.nextElement();if(!e.getName().endsWith(".class"))continue;String s=mod+"!"+e.getName();try(InputStream in=j.getInputStream(e)){new ClassReader(in).accept(new ClassVisitor(Opcodes.ASM9){public void visit(int v,int a,String n,String sig,String sup,String[] it){cls(sup,s);if(it!=null)for(String x:it)cls(x,s);}public AnnotationVisitor visitAnnotation(String d,boolean vis){typ(Type.getType(d),s);return ann(s);}public FieldVisitor visitField(int a,String n,String d,String sig,Object v){typ(Type.getType(d),s);return null;}public MethodVisitor visitMethod(int a,String n,String d,String sig,String[] ex){typ(Type.getMethodType(d),s);if(ex!=null)for(String x:ex)cls(x,s);return new MethodVisitor(Opcodes.ASM9){public void visitTypeInsn(int op,String t){cls(t,s);}public void visitFieldInsn(int op,String o,String n,String d){typ(Type.getType(d),s);check(o,n,d,false,s);}public void visitMethodInsn(int op,String o,String n,String d,boolean it){typ(Type.getMethodType(d),s);check(o,n,d,true,s);}public void visitLdcInsn(Object v){if(v instanceof Type t)typ(t,s);else if(v instanceof Handle h)handle(h,s);else if(v instanceof ConstantDynamic c){typ(Type.getType(c.getDescriptor()),s);handle(c.getBootstrapMethod(),s);for(int x=0;x<c.getBootstrapMethodArgumentCount();x++){Object a=c.getBootstrapMethodArgument(x);if(a instanceof Type t)typ(t,s);else if(a instanceof Handle h)handle(h,s);}}}public void visitInvokeDynamicInsn(String n,String d,Handle b,Object...a){typ(Type.getMethodType(d),s);handle(b,s);for(Object x:a){if(x instanceof Type t)typ(t,s);else if(x instanceof Handle h)handle(h,s);}}public void visitMultiANewArrayInsn(String d,int n){typ(Type.getType(d),s);}public void visitTryCatchBlock(Label a,Label b,Label c,String t){cls(t,s);}};}},ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}}}}
 static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n");}
 static void out(Writer w,Map<String,Set<String>> m)throws Exception{w.write("{");boolean f=true;for(var e:m.entrySet()){if(!f)w.write(",");f=false;w.write("\n    \""+esc(e.getKey())+"\":[");boolean g=true;for(String x:e.getValue()){if(!g)w.write(",");g=false;w.write("\""+esc(x)+"\"");}w.write("]");}if(!m.isEmpty())w.write("\n  ");w.write("}");}
 public static void main(String[] a)throws Exception{if(a.length<2)throw new IllegalArgumentException("Usage: ModAbiAudit <shim.jar> <mod.jar>...");load(Path.of(a[0]));for(int x=1;x<a.length;x++)scan(Path.of(a[x]));for(var e:refs.entrySet())if(!shim.containsKey(e.getKey()))mc.put(e.getKey(),e.getValue());int count=mm.values().stream().mapToInt(Set::size).sum();System.out.println("Shim classes: "+shim.size()+"; referenced Minecraft classes: "+refs.size()+"; missing classes: "+mc.size()+"; missing members: "+count);mc.entrySet().stream().sorted((x,y)->Integer.compare(y.getValue().size(),x.getValue().size())).limit(100).forEach(e->System.out.println("MISSING CLASS "+e.getKey()+" ("+e.getValue().size()+" refs)"));mm.forEach((c,s)->{System.out.println("MISSING MEMBERS "+c);s.forEach(System.out::println);});String file=System.getenv().getOrDefault("POMME_ABI_REPORT","pomme-abi-report.json");try(Writer w=Files.newBufferedWriter(Path.of(file))){w.write("{\n \"shimClassCount\":"+shim.size()+",\n \"referencedMinecraftClassCount\":"+refs.size()+",\n \"missingClassCount\":"+mc.size()+",\n \"missingMemberCount\":"+count+",\n \"missingClasses\":");out(w,mc);w.write(",\n \"missingMembers\":");out(w,mm);w.write(",\n \"referencedClasses\":");out(w,refs);w.write("\n}\n");}System.out.println("Report: "+file);}
}